const dl_routine_info *dl_routine_lookup(int32_t id)
{
	size_t lo = 0, hi = DL_ROUTINE_COUNT;
	while (lo < hi) {
		size_t mid = (lo + hi) / 2;
		if (dl_routines[mid].id == id)
			return &dl_routines[mid];
		if (dl_routines[mid].id < id)
			lo = mid + 1;
		else
			hi = mid;
	}
	return NULL;
}
